student_window=None  # 真正选区后填写 {'left':..., 'a':..., 'b':..., 'right':...}，单位BKJD天
student_measurements=[]
student_measurement_status={'status':'not_started','reason':'学生尚未填写真实Q3选区'}
if student_window is not None:
    bounds={key:float(student_window[key]) for key in ['left','a','b','right']}
    try:
        result,student_inside,student_outside=local_relative_depth(q3_flat_initial.time.value,q3_flat_initial.flux.value,**bounds)
        result.update(bounds);result['event_id']='student-event-01';result['data_kind']='student-selected Q3 window'
        student_measurements.append(result)
        student_measurement_status={'status':'computed','reason':'仅已计算，不自动宣称可靠下降'}
        selected=student_inside|student_outside
        save_csv('M13/selected-observations.csv',['cadenceno','time_bkjd','detrended_flux','inside','outside'],
                 [[int(q3_flat_initial.cadenceno[j]),float(q3_flat_initial.time.value[j]),float(q3_flat_initial.flux.value[j]),bool(student_inside[j]),bool(student_outside[j])] for j in np.flatnonzero(selected)])
        fig,ax=plt.subplots(figsize=(9,4));ax.scatter(q3_flat_initial.time.value[selected],q3_flat_initial.flux.value[selected],s=12)
        ax.axvspan(bounds['a'],bounds['b'],alpha=.15);ax.set(xlabel='Student-selected BKJD [day]',ylabel='Detrended relative flux')
        fig.tight_layout();save_plot('M13/student-window.png');plt.close(fig)
        print(result)
    except ValueError as error:
        student_measurement_status={'status':'cannot_measure','reason':str(error)}
print(student_measurement_status)
save_json('M13/student-window-status.json',student_measurement_status)
save_csv('M13/event-measurements.csv',['event_id','left','a','b','right','baseline','inside_mean','relative_depth_ppm','n_in','n_out','minimum','data_kind'],student_measurements)

constructed_centres=[('A',10.0),('B',10.8),('C',12.4)]
interval_rows=[]
for previous,current in zip(constructed_centres[:-1],constructed_centres[1:]):
    interval=current[1]-previous[1]
    for assumed_cycles in [1,2,3]:
        interval_rows.append([previous[0],current[0],previous[1],current[1],interval,assumed_cycles,interval/assumed_cycles,'constructed'])
print('from,to,t_from,t_to,interval,assumed_cycles,trial_period,data_kind')
for row in interval_rows: print(row)
save_csv('M14/constructed-intervals.csv',['from_event','to_event','from_day','to_day','interval_day','assumed_cycles','trial_period_day','data_kind'],interval_rows)
student_centres=None  # 可填写本人事件表，例如 [{'event_id':'自己的编号','centre_bkjd':...}, ...]；不能复制上面的构造值
real_interval_rows=[]
if student_centres is None or len(student_centres)<2:
    interval_status={'status':'insufficient_event_centres','reason':'尚无至少两个本人定位的真实中心；构造练习可继续'}
else:
    ordered=sorted(student_centres,key=lambda item:item['centre_bkjd'])
    for previous,current in zip(ordered[:-1],ordered[1:]):
        delta=float(current['centre_bkjd'])-float(previous['centre_bkjd'])
        if delta<=0: raise ValueError('中心重复或顺序有误；回查事件ID')
        for assumed_cycles in [1,2,3]:
            real_interval_rows.append([previous['event_id'],current['event_id'],previous['centre_bkjd'],current['centre_bkjd'],delta,assumed_cycles,delta/assumed_cycles,'student Q3 measurement'])
    interval_status={'status':'computed_trial_intervals','reason':'候选仍需覆盖与形状检查'}
save_csv('M14/event-intervals.csv',['from_event','to_event','from_bkjd','to_bkjd','interval_day','assumed_cycles','trial_period_day','data_kind'],real_interval_rows)
save_json('M14/interval-status.json',interval_status);print(interval_status)
